from pathlib import Path

paths = [Path('index.html'), Path('.github/update_full_diary.py')]

replacements = {
    'Мне выгодно думать, что всё складывается для меня хорошо.': 'Всё складывается для меня хорошо.',
    'Мне выгодно думать, что контакт с ней уже есть, она отвечает, наше общение продолжается и мне легко и естественно с ней общаться.': 'Контакт с ней уже есть, она отвечает, наше общение продолжается, и мне легко и естественно с ней общаться.',
    'Мне выгодно думать, что контакт с Яной уже есть, она отвечает, наше общение продолжается и мне легко и естественно с ней общаться.': 'Контакт с ней уже есть, она отвечает, наше общение продолжается, и мне легко и естественно с ней общаться.',
    'Мне выгодно думать, что между нами есть тепло, ясность и взаимность.': 'Между нами есть тепло, ясность и взаимность.',
    'Мне выгодно думать, что между мной и Яной есть тепло, ясность и взаимность.': 'Между нами есть тепло, ясность и взаимность.',
    'Мне выгодно ожидать хорошего.': 'Я ожидаю хорошего.',
    'Игорь классно ко мне относится, считает, что я супер, вообще лучший его партнер по бизнесу. Игорь считает, что я его лучший друг. И считает, что я очень умный, деятельный, в принципе, гений.': 'Люди ценят меня, хорошо ко мне относятся, считают меня умным, деятельным, сильным партнёром и хорошим другом.',

    # Keep the source corpus neutral too, so future rebuilds do not restore a name.
    'Наше общение с Яной': 'Наше общение с ней',
    'наше общение с Яной': 'наше общение с ней',
    'между мной и Яной': 'между нами',
    'контакт с Яной': 'контакт с ней',
    'Мы с Яной': 'Мы',
    'Наш с Яной контакт': 'Наш контакт',
    'наши отношения с Яной': 'наши отношения',
    'Яна сама': 'Она сама',
    'Яна хочет': 'Она хочет',
    'Яна ценит': 'Она ценит',
}

for p in paths:
    text = p.read_text(encoding='utf-8')
    before = text
    for old, new in replacements.items():
        text = text.replace(old, new)
    p.write_text(text, encoding='utf-8')
    print(f'{p}: changed={text != before}')

# App-facing validation: no framing phrase and no known personal names in cards.
app = Path('index.html').read_text(encoding='utf-8')
for forbidden in ['Мне выгодно думать', 'Мне выгодно ожидать', 'Игорь', 'Яна', 'Максим', 'Дима', 'Джулия', 'Серджио']:
    if forbidden in app:
        raise SystemExit(f'Forbidden wording/name remains in index.html: {forbidden}')
print('Validation passed')
